using System.Security.Claims; using Asp.Versioning; using FluentValidation; using LostFound.Application.Contracts; using LostFound.Domain.Entities; using LostFound.Infrastructure.Persistence; using Microsoft.AspNetCore.Authorization; using Microsoft.AspNetCore.Mvc; using Microsoft.EntityFrameworkCore;
namespace LostFound.Api.Controllers;
[ApiController,ApiVersion(1),Route("api/v{version:apiVersion}/ratings")] public sealed class RatingsController(LostFoundDbContext db,IValidator<RatingRequest> validator):ControllerBase{private Guid UserId=>Guid.Parse(User.FindFirstValue(ClaimTypes.NameIdentifier)!);[Authorize,HttpPost]public async Task<ActionResult> Create(RatingRequest r,CancellationToken ct){var vr=await validator.ValidateAsync(r,ct);if(!vr.IsValid)return BadRequest(new ValidationProblemDetails(vr.ToDictionary()));var exchange=await db.Exchanges.AsNoTracking().Where(x=>x.Id==r.ExchangeId).Select(x=>new{x.CompletedAtUtc,Claimant=x.Claim.ClaimantId,Owner=x.Claim.Item.OwnerId}).SingleOrDefaultAsync(ct);if(exchange is null||exchange.CompletedAtUtc is null)return Conflict(new ProblemDetails{Title="A completed exchange is required",Status=409});if(UserId!=exchange.Claimant&&UserId!=exchange.Owner)return Forbid();var reviewee=UserId==exchange.Claimant?exchange.Owner:exchange.Claimant;if(reviewee==UserId)return BadRequest();if(await db.Ratings.AnyAsync(x=>x.ExchangeId==r.ExchangeId&&x.ReviewerId==UserId&&x.RevieweeId==reviewee,ct))return Conflict(new ProblemDetails{Title="Exchange already rated",Status=409});var rating=new Rating{ExchangeId=r.ExchangeId,ReviewerId=UserId,RevieweeId=reviewee,Score=r.Score,Review=r.Review?.Trim()};db.Add(rating);await db.SaveChangesAsync(ct);return Created($"/api/v1/ratings/{rating.Id}",new{rating.Id});}[HttpGet("users/{userId:guid}/summary")]public async Task<ActionResult> Summary(Guid userId,CancellationToken ct){var q=db.Ratings.Where(x=>x.RevieweeId==userId);return Ok(new{average=await q.AnyAsync(ct)?await q.AverageAsync(x=>(decimal)x.Score,ct):0,count=await q.CountAsync(ct)});}}
